pushToWrite — static accumulator design:
```c
void pushToWrite(Buffer *buf, unsigned char *source, size_t size, unsigned int addr, bool reset, bool push)
{
    static unsigned char acc[BLK_SIZE];
    static size_t size_ = 0;
    static size_t count = 0;
    static unsigned int nextAddr = 0;

    if (reset) {
        size_ = 0; count = 0; nextAddr = addr;
        return;
    }
    if (size_ == 0 && size > 0) size_ = size;
    size_t cap = (BLK_SIZE - 8) / size_;  // items per block
    if (source != NULL && size > 0) {
        memcpy(acc + count * size_, source, size);
        count++;
        if (count == cap) { flush full block with next = nextAddr+1 }
    }
    if (push && count > 0) { flush partial with next = 0 }
}
```

