getNewBlockInBuffer:
```c
unsigned char *getNewBlockInBuffer(Buffer *buf)
{
	unsigned char *blkPtr;

	if (buf->numFreeBlk == 0)
	{
		perror("Buffer is full!\n");
		return NULL;
	}

	blkPtr = buf->data;
	while (blkPtr < buf->data + buf->bufSize)
	{
		if (*blkPtr == BLOCK_AVAILABLE)
			break;
		else
			blkPtr += buf->blkSize + 1;
	}

	*blkPtr = BLOCK_UNAVAILABLE;
	buf->numFreeBlk--;

	return blkPtr + 1;
}
```

freeBlockInBuffer:
