```c
/* internal helper: flush accumulated items of pushToWrite into one disk block */
static void flushWriteBlock(Buffer *buf, unsigned char *acc, size_t itemSize, size_t count, unsigned int addr, int last)
{
    unsigned char block[BLK_SIZE];
    unsigned char *blk;
