/* Rewrite the next-block pointer of an already-flushed block to 0, marking
 * it as the end of its chain. Needed when a stream/bucket length is an exact
 * multiple of the block capacity, so no partial tail block ever follows.
 */
static void terminateChain(Buffer *buf, unsigned int addr, size_t nextOffset)
{
	unsigned char *blk = readBlockFromDisk(addr, buf);

	if (blk == NULL)
		return;
	*(int *)(blk + nextOffset) = 0;
	writeBlockToDisk(blk, addr, buf);
}

